local CatapultMaker = {}
local PRODUCTS = {
    mangonel = { name = "Mangonel", woodCost = 6, ironCost = 3, ropeCost = 2, time = 6, cost = 350, attack = 35, range = 200, durability = 40, description = "Majhen mangonel za hitro obleganje." },
    onager = { name = "Onager", woodCost = 8, ironCost = 4, ropeCost = 3, time = 9, cost = 800, attack = 55, range = 250, durability = 55, prestige = 3, description = "Onager z močno napetostjo." },
    standard_catapult = { name = "Standardni katapult", woodCost = 10, ironCost = 5, ropeCost = 4, leatherCost = 2, time = 12, cost = 1600, attack = 80, range = 300, durability = 70, prestige = 6, happiness = 1, description = "Standardni katapult za obleganje." },
    heavy_catapult = { name = "Težki katapult", woodCost = 12, ironCost = 7, steelCost = 2, ropeCost = 5, leatherCost = 3, time = 16, cost = 3200, attack = 120, range = 350, durability = 90, prestige = 12, happiness = 2, description = "Težki katapult za velike oblege." },
    silver_reinforced_catapult = { name = "Srebrno ojačan katapult", woodCost = 12, ironCost = 5, steelCost = 3, silverCost = 2, ropeCost = 5, leatherCost = 3, time = 19, cost = 5800, attack = 160, range = 400, durability = 110, prestige = 22, happiness = 4, description = "Katapult s srebrnim ojačitvami za kraljevo vojsko." },
    royal_grand_catapult = { name = "Kraljevski veliki katapult", woodCost = 18, ironCost = 8, steelCost = 5, goldCost = 3, silverCost = 2, ropeCost = 8, leatherCost = 5, jewelCost = 1, time = 26, cost = 12000, attack = 240, range = 500, durability = 160, prestige = 60, happiness = 12, description = "Veliki kraljevski katapult z zlatim in draguljnim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Katapultarska delavnica", cost = { gold = 500, wood = 250, stone = 200 }, upkeep = 12, qualityBonus = 5 },
    siege_yard = { name = "Oblegovalno dvorišče", cost = { gold = 1500, wood = 400, stone = 400, iron = 12 }, upkeep = 30, qualityBonus = 18 },
    tension_room = { name = "Napetilnica", cost = { gold = 3500, wood = 500, stone = 700, silver = 40, rope = 10 }, upkeep = 70, qualityBonus = 30 },
    royal_siege_atelier = { name = "Kraljevski atelje oblegovalnih naprav", cost = { gold = 15000, wood = 1000, stone = 1500, gold = 200, jewel = 30 }, upkeep = 300, qualityBonus = 55, prestigeBonus = 50 },
}
CatapultMaker.woodStock = 24; CatapultMaker.ironStock = 14; CatapultMaker.steelStock = 10; CatapultMaker.ropeStock = 12; CatapultMaker.leatherStock = 10; CatapultMaker.silverStock = 8; CatapultMaker.goldStock = 6; CatapultMaker.jewelStock = 6
CatapultMaker.productStock = {}; CatapultMaker.buildings = {}; CatapultMaker.maker = nil; CatapultMaker.activeMaking = {}; CatapultMaker.totalProducts = 0; CatapultMaker.dayTimer = 0
function CatapultMaker.init() CatapultMaker.woodStock=24; CatapultMaker.ironStock=14; CatapultMaker.steelStock=10; CatapultMaker.ropeStock=12; CatapultMaker.leatherStock=10; CatapultMaker.silverStock=8; CatapultMaker.goldStock=6; CatapultMaker.jewelStock=6; CatapultMaker.productStock={}; CatapultMaker.buildings={}; CatapultMaker.maker=nil; CatapultMaker.activeMaking={}; CatapultMaker.totalProducts=0; CatapultMaker.dayTimer=0; print("[CatapultMaker] Royal Catapult Maker System initialized (6 products, 4 buildings)") end
function CatapultMaker.hireMaker(n,s) s=s or math.random(55,95); local c=700+s*15; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CatapultMaker.maker={name=n or ("Katapultar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Katapultar najet: %s (spretnost: %d)",CatapultMaker.maker.name,s),"success") end; return true end
function CatapultMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CatapultMaker.build(id) local ok,e=CatapultMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CatapultMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CatapultMaker.getQualityBonus() local b=0; for _,bd in ipairs(CatapultMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CatapultMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and CatapultMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and CatapultMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and CatapultMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.ropeCost and CatapultMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.leatherCost and CatapultMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CatapultMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CatapultMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CatapultMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #CatapultMaker.buildings==0 then return false,"Potrebna delavnica" end; if not CatapultMaker.maker then return false,"Potreben katapultar" end; return true end
function CatapultMaker.make(pt,qty) qty=qty or 1; local ok,e=CatapultMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then CatapultMaker.woodStock=CatapultMaker.woodStock-d.woodCost*qty end; if d.ironCost then CatapultMaker.ironStock=CatapultMaker.ironStock-d.ironCost*qty end; if d.steelCost then CatapultMaker.steelStock=CatapultMaker.steelStock-d.steelCost*qty end; if d.ropeCost then CatapultMaker.ropeStock=CatapultMaker.ropeStock-d.ropeCost*qty end; if d.leatherCost then CatapultMaker.leatherStock=CatapultMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CatapultMaker.silverStock=CatapultMaker.silverStock-d.silverCost*qty end; if d.goldCost then CatapultMaker.goldStock=CatapultMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CatapultMaker.jewelStock=CatapultMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if CatapultMaker.maker then t=math.max(1,t-math.floor(CatapultMaker.maker.skill/12)) end; table.insert(CatapultMaker.activeMaking,{id="catapult_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,range=d.range or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CatapultMaker.completeMaking(m) local q=1.0+(CatapultMaker.getQualityBonus()/100); if CatapultMaker.maker then q=q+(CatapultMaker.maker.skill/150) end; q=math.min(2.5,q); CatapultMaker.productStock[m.productType]=(CatapultMaker.productStock[m.productType] or 0)+m.quantity; CatapultMaker.totalProducts=CatapultMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CatapultMaker.maker then CatapultMaker.maker.itemsMade=CatapultMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CatapultMaker.maker.skill=math.min(100,CatapultMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Katapult izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"catapult.completed",{productName=m.productName,attack=m.attack,range=m.range,durability=m.durability}) end end
function CatapultMaker.update(dt) if not _G.state then return end; CatapultMaker.dayTimer=CatapultMaker.dayTimer+dt; if CatapultMaker.dayTimer>=30 then CatapultMaker.dayTimer=0; for i=#CatapultMaker.activeMaking,1,-1 do local m=CatapultMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CatapultMaker.completeMaking(m); table.remove(CatapultMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CatapultMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CatapultMaker.maker then tu=tu+25 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CatapultMaker.getStats() return {woodStock=CatapultMaker.woodStock,ironStock=CatapultMaker.ironStock,steelStock=CatapultMaker.steelStock,ropeStock=CatapultMaker.ropeStock,leatherStock=CatapultMaker.leatherStock,silverStock=CatapultMaker.silverStock,goldStock=CatapultMaker.goldStock,jewelStock=CatapultMaker.jewelStock,productStock=CatapultMaker.productStock,numBuildings=#CatapultMaker.buildings,hasMaker=CatapultMaker.maker~=nil,makerName=CatapultMaker.maker and CatapultMaker.maker.name or "—",makerSkill=CatapultMaker.maker and CatapultMaker.maker.skill or 0,activeMaking=#CatapultMaker.activeMaking,totalProducts=CatapultMaker.totalProducts} end
return CatapultMaker
